# Load model
model = tf.keras.models.load_model("cnn_model.h5")

# Inference
print("Classifying Disease with Keras...")
start_time = time.time()
predictions = model.predict(input_data, verbose=0)
inference_time = time.time() - start_time

predicted_classes = np.argmax(predictions, axis=1)

# Results
unique, counts = np.unique(predicted_classes, return_counts=True)
print(f"\nInference Time for {len(predicted_classes)} samples: {inference_time:.4f} seconds")
print("\nPrediction Distribution:")
for i, count in zip(unique, counts):
    print(f"{class_labels[i]}: {(count / len(predicted_classes)) * 100:.2f}%")

# Plot
plt.figure(figsize=(8, 4))
plt.bar([class_labels[i] for i in unique], counts, color='skyblue')
plt.title('Keras: Predicted Class Distribution')
plt.xlabel('Class')
plt.ylabel('Samples')
plt.xticks(rotation=20)
plt.tight_layout()
plt.show()
